+/*! \brief The table kind for OP, if OP is read from a table. */
+template <typename ParamOP, float (*OP)(float, const ParamOP &)>
+constexpr bool kHasTable = false;
+template <typename ParamOP, float (*OP)(float, const ParamOP &)>
+constexpr Kind kKindOf = kGelu;
